export const BUNDLED_MIGRATIONS: readonly BundledMigration[] = [
  { name: "001_init.sql", sql: "-- Gate 1: config, the ledger, items, expenses.\n-- Written close to ANSI. Money is INTEGER cents; rates are INTEGER bps.\n-- Future enum values (APPROVED / ARMED) are already inside CHECK constraints so\n-- adding them later is not a migration of live rows.\n\nCREATE TABLE config (\n  key         TEXT PRIMARY KEY,\n  value_json  TEXT NOT NULL,\n  updated_at  TEXT NOT NULL\n);\n\nCREATE TABLE items (\n  item_id                TEXT PRIMARY KEY,\n  opportunity_id         TEXT NULL,\n  name                   TEXT NOT NULL,\n  category               TEXT NOT NULL,\n  sku                    TEXT NULL,\n  condition              TEXT NULL,\n  acquired_at            TEXT NOT NULL,\n  landed_cost_cents      INTEGER NOT NULL,\n  book_value_cents       INTEGER NOT NULL,\n  expected_days_to_sale  INTEGER NOT NULL,\n  expected_resale_cents  INTEGER NOT NULL,\n  state                  TEXT NOT NULL CHECK (state IN (\n                           'ACTIVE','MARKDOWN','CAPITAL_RECOVERY','SOLD',\n                           'CHARGED_OFF','PASSIVE_RECOVERY','PERSONAL_KEEP')),\n  charge_off_reason      TEXT NULL CHECK (charge_off_reason IS NULL OR charge_off_reason IN (\n                           'UNSELLABLE','DAMAGED','LOST','PERSONAL_KEEP','STALE')),\n  listing_live           INTEGER NOT NULL DEFAULT 0 CHECK (listing_live IN (0,1)),\n  marketplace            TEXT NULL,\n  sold_at                TEXT NULL,\n  days_to_sale           INTEGER NULL,\n  realized_profit_cents  INTEGER NOT NULL DEFAULT 0,\n  updated_at             TEXT NOT NULL\n);\n\nCREATE TABLE ledger_events (\n  id            INTEGER PRIMARY KEY,\n  event_id      TEXT NOT NULL UNIQUE,\n  type          TEXT NOT NULL CHECK (type IN (\n                  'CONTRIBUTION','PURCHASE','SALE','OWNER_PAYOUT',\n                  'BUSINESS_EXPENSE','TAX_PAYMENT','CHARGE_OFF',\n                  'PASSIVE_RECOVERY','ITEM_STATE_CHANGE','ADJUSTMENT')),\n  occurred_at   TEXT NOT NULL,\n  recorded_at   TEXT NOT NULL,\n  item_id       TEXT NULL REFERENCES items(item_id),\n  memo          TEXT NULL,\n  payload_json  TEXT NOT NULL,\n  prev_hash     TEXT NULL,\n  hash          TEXT NOT NULL\n);\n\nCREATE TABLE ledger_postings (\n  id            INTEGER PRIMARY KEY,\n  event_id      TEXT NOT NULL REFERENCES ledger_events(event_id),\n  seq           INTEGER NOT NULL,\n  account       TEXT NOT NULL CHECK (account IN (\n                  'LIQUID','INVENTORY_AT_COST','TAX_RESERVE','OPERATING_RESERVE',\n                  'OWNER_PAYABLE','CONTRIBUTED_CAPITAL','RETAINED_EARNINGS')),\n  amount_cents  INTEGER NOT NULL,\n  memo          TEXT NULL,\n  UNIQUE (event_id, seq)\n);\n\nCREATE TABLE expenses (\n  expense_id    TEXT PRIMARY KEY,\n  event_id      TEXT NOT NULL REFERENCES ledger_events(event_id),\n  scope         TEXT NOT NULL CHECK (scope IN ('TRANSACTION','BUSINESS')),\n  item_id       TEXT NULL REFERENCES items(item_id),\n  category      TEXT NOT NULL,\n  amount_cents  INTEGER NOT NULL,\n  occurred_at   TEXT NOT NULL,\n  memo          TEXT NULL,\n  -- 1 when the cost was capitalised into an item's book value (acquisition\n  -- travel, inbound shipping). Reporting must not count those twice.\n  capitalized   INTEGER NOT NULL DEFAULT 0 CHECK (capitalized IN (0,1)),\n  CHECK (scope = 'BUSINESS' OR item_id IS NOT NULL)\n);\n\nCREATE INDEX idx_postings_account ON ledger_postings(account);\nCREATE INDEX idx_postings_event   ON ledger_postings(event_id);\nCREATE INDEX idx_events_occurred  ON ledger_events(occurred_at);\nCREATE INDEX idx_events_item      ON ledger_events(item_id);\nCREATE INDEX idx_items_state      ON items(state);\nCREATE INDEX idx_items_category   ON items(category, state);\nCREATE INDEX idx_expenses_scope   ON expenses(scope, occurred_at);\n" },
  { name: "002_opportunities.sql", sql: "-- Gate 2: opportunities, and the authorization table that autonomous purchasing\n-- will one day need.\n--\n-- The status CHECK already includes APPROVED and ARMED, so adding them later is\n-- a code change rather than a migration of live rows. NOTHING in this codebase\n-- transitions into either state.\n\nCREATE TABLE opportunities (\n  opportunity_id            TEXT PRIMARY KEY,\n  created_at                TEXT NOT NULL,\n  updated_at                TEXT NOT NULL,\n\n  name                      TEXT NOT NULL,\n  category                  TEXT NOT NULL,\n  source                    TEXT NOT NULL DEFAULT 'MANUAL',\n  source_url                TEXT NULL,\n  source_listing_id         TEXT NULL,\n  marketplace               TEXT NOT NULL DEFAULT 'EBAY',\n\n  -- what it costs\n  asking_price_cents        INTEGER NOT NULL,\n  inbound_shipping_cents    INTEGER NOT NULL DEFAULT 0,\n  sales_tax_cents           INTEGER NOT NULL DEFAULT 0,\n  acquisition_travel_cents  INTEGER NOT NULL DEFAULT 0,\n  landed_cost_cents         INTEGER NOT NULL,\n\n  -- what it should return. expected_gross is BEFORE fees; the rest is derived.\n  expected_gross_cents      INTEGER NOT NULL,\n  marketplace_fee_cents     INTEGER NOT NULL,\n  postage_cents             INTEGER NOT NULL,\n  packaging_cents           INTEGER NOT NULL,\n  net_proceeds_cents        INTEGER NOT NULL,\n  expected_profit_cents     INTEGER NOT NULL,\n  expected_roi_bps          INTEGER NOT NULL,\n  modeled_downside_cents    INTEGER NOT NULL,\n\n  -- the evidence the hold time was derived from\n  sold_last_90d             INTEGER NULL,\n  active_listings           INTEGER NOT NULL DEFAULT 0,\n  velocity_source           TEXT NOT NULL CHECK (velocity_source IN ('COMPS','OPERATOR_ESTIMATE')),\n  sell_through_bps          INTEGER NOT NULL,\n  expected_days_to_sale     INTEGER NOT NULL,\n  expected_days_p90         INTEGER NOT NULL,\n\n  -- the verdict\n  buy_score                 INTEGER NULL,\n  risk_score                INTEGER NULL,\n  confidence_bps            INTEGER NULL,\n  max_recommended_cents     INTEGER NULL,\n  price_bound_by            TEXT NULL,\n  recommendation            TEXT NULL CHECK (recommendation IS NULL OR recommendation IN\n                              ('BUY','WATCH','PASS','REJECT')),\n  reasoning_json            TEXT NULL,\n  score_breakdown_json      TEXT NULL,\n  scored_at                 TEXT NULL,\n  -- A score means nothing without the rules that produced it.\n  policy_version            TEXT NULL,\n\n  status                    TEXT NOT NULL CHECK (status IN (\n                              'WATCHING','ELIGIBLE','RECOMMENDED','PASSED',\n                              'APPROVED','ARMED','PURCHASED')),\n  -- Set when a PURCHASED opportunity became a real item.\n  item_id                   TEXT NULL REFERENCES items(item_id),\n  input_json                TEXT NOT NULL,\n\n  UNIQUE (source, source_listing_id)\n);\n\n-- Architecture only. There is deliberately NO code path that inserts here.\n-- The system never grants itself spending authority.\nCREATE TABLE authorizations (\n  authorization_id   TEXT PRIMARY KEY,\n  opportunity_id     TEXT NULL REFERENCES opportunities(opportunity_id),\n  scope              TEXT NOT NULL CHECK (scope IN ('ITEM','SKU','CATEGORY')),\n  granted_by         TEXT NOT NULL,\n  granted_at         TEXT NOT NULL,\n  expires_at         TEXT NOT NULL,\n  max_price_cents    INTEGER NOT NULL,\n  max_quantity       INTEGER NOT NULL,\n  allowed_retailers  TEXT NOT NULL,\n  state              TEXT NOT NULL CHECK (state IN\n                       ('APPROVED','ARMED','DISARMED','EXPIRED','CONSUMED')),\n  disarmed_at        TEXT NULL,\n  disarm_reason      TEXT NULL\n);\n\nCREATE INDEX idx_opps_status ON opportunities(status, buy_score);\nCREATE INDEX idx_opps_category ON opportunities(category, status);\nCREATE INDEX idx_opps_created ON opportunities(created_at);\nCREATE INDEX idx_auth_state ON authorizations(state, expires_at);\n" },
  { name: "003_item_predictions.sql", sql: "-- Gate 3: make prediction accuracy measurable.\n--\n-- `expected_resale_cents` is a GROSS price; what an item actually realises is\n-- NET of fees and postage. Comparing them was comparing different things, so\n-- the expectation is now stored in the same terms as the outcome.\n--\n-- All three are nullable: items bought before this migration, and items bought\n-- without a scored opportunity behind them, genuinely have no prediction. A\n-- zero would be a lie about a number nobody produced.\n\nALTER TABLE items ADD COLUMN expected_net_proceeds_cents INTEGER NULL;\nALTER TABLE items ADD COLUMN expected_profit_cents INTEGER NULL;\nALTER TABLE items ADD COLUMN actual_net_proceeds_cents INTEGER NULL;\n\nCREATE INDEX idx_items_opportunity ON items(opportunity_id);\n" },
  { name: "004_expense_reversal.sql", sql: "-- Gate 4 / backlog B33: an ADJUSTMENT that corrects an expense must correct the\n-- analytic record too.\n--\n-- Business expenses live in two places: the ledger (a posting against\n-- RETAINED_EARNINGS) and this table (the category breakdown behind operating\n-- profit). An ADJUSTMENT reversing an expense moved only the ledger, so\n-- `profit` and the ledger could disagree — found at button-up, where the ledger\n-- returned to $50.00 while `profit --expenses` still reported $1.50 of SUPPLIES.\n--\n-- A reversal now writes a compensating row here with a NEGATIVE amount, and\n-- this column is what links it back to the expense it undoes. Nothing is ever\n-- deleted or edited: the table stays append-only like the ledger it mirrors.\n--\n-- Nullable because every row written before now — and every ordinary expense —\n-- reverses nothing.\n\nALTER TABLE expenses ADD COLUMN reverses_event_id TEXT NULL REFERENCES ledger_events(event_id);\n\nCREATE INDEX idx_expenses_reverses ON expenses(reverses_event_id);\nCREATE INDEX idx_expenses_event ON expenses(event_id);\n" },
  { name: "005_expense_correction.sql", sql: "-- self-managed\n--\n-- Gate 4 / D9: a correction to the analytic record that moves no cash.\n--\n-- Two things need it. A miscategorised expense (SUPPLIES that was really\n-- POSTAGE) is a books error, not a money error. And an expense whose cash was\n-- already returned by an ADJUSTMENT recorded before `reversesEventId` existed\n-- has a ledger that is right and an `expenses` table that is wrong, with no\n-- command able to say so — the live book's $1.50 of smoke-test SUPPLIES.\n--\n-- ⚠️ This file is `-- self-managed`: it runs outside the runner's transaction\n-- and owns its own. SQLite cannot alter a CHECK constraint in place, so a new\n-- event type means rebuilding `ledger_events`, and rebuilding a table that\n-- `ledger_postings` and `expenses` both reference needs foreign keys genuinely\n-- OFF. `PRAGMA defer_foreign_keys` was tried first and does not survive the\n-- DROP; it fails with a foreign key violation.\n--\n-- It is written to be safe to re-run: the scratch table is dropped first and\n-- the indexes are IF NOT EXISTS, so a crash before the runner records this file\n-- is recovered by simply running it again.\n\nPRAGMA foreign_keys = OFF;\n\nBEGIN;\n\nDROP TABLE IF EXISTS ledger_events_new;\n\nCREATE TABLE ledger_events_new (\n  id            INTEGER PRIMARY KEY,\n  event_id      TEXT NOT NULL UNIQUE,\n  type          TEXT NOT NULL CHECK (type IN (\n                  'CONTRIBUTION','PURCHASE','SALE','OWNER_PAYOUT',\n                  'BUSINESS_EXPENSE','TAX_PAYMENT','CHARGE_OFF',\n                  'PASSIVE_RECOVERY','ITEM_STATE_CHANGE','ADJUSTMENT',\n                  'EXPENSE_CORRECTION')),\n  occurred_at   TEXT NOT NULL,\n  recorded_at   TEXT NOT NULL,\n  item_id       TEXT NULL REFERENCES items(item_id),\n  memo          TEXT NULL,\n  payload_json  TEXT NOT NULL,\n  prev_hash     TEXT NULL,\n  hash          TEXT NOT NULL\n);\n\n-- Column-for-column, so the hash chain is byte-identical afterwards.\nINSERT INTO ledger_events_new\n  (id, event_id, type, occurred_at, recorded_at, item_id, memo, payload_json, prev_hash, hash)\nSELECT\n   id, event_id, type, occurred_at, recorded_at, item_id, memo, payload_json, prev_hash, hash\n  FROM ledger_events;\n\nDROP TABLE ledger_events;\n\nALTER TABLE ledger_events_new RENAME TO ledger_events;\n\nCREATE INDEX IF NOT EXISTS idx_events_occurred ON ledger_events(occurred_at);\nCREATE INDEX IF NOT EXISTS idx_events_item     ON ledger_events(item_id);\n\nCOMMIT;\n\nPRAGMA foreign_keys = ON;\n" },
  { name: "006_purchase_override.sql", sql: "-- D4, answered 2026-09-09: a purchase may overrule the capital gates, and it\n-- may never do so silently.\n--\n-- Before this, `cli buy --force` printed \"recording it as it happened\" and\n-- committed an ordinary PURCHASE with no marker of any kind, so an overruled\n-- buy was indistinguishable from a clean one the moment the terminal scrolled.\n-- That was live on the real fund.\n--\n-- `overrode_gates` is the JSON array of failed constraint codes as they read at\n-- the time of purchase. Stored as text rather than normalised: the codes are a\n-- historical record of what the rules said THEN, not a foreign key into what\n-- they say now, and joining against a live rule set would rewrite history every\n-- time a constraint is renamed.\n--\n-- Both are NULL for a clean purchase. NULL means \"no override\", which is a\n-- different fact from an empty array, and the two must not collapse.\n\nALTER TABLE items ADD COLUMN overrode_gates TEXT NULL;\nALTER TABLE items ADD COLUMN override_reason TEXT NULL;\n" },
];
